1: import type {
2:   KnowledgeEntity,
3:   KnowledgeRelation,
4: } from '../services/knowledgeGraphService';
5: 
6: const MAX_DESCRIPTION_LENGTH = 96;
7: 
8: export interface KnowledgeCodeLensModel {
9:   entityId: string;
10:   line: number;
11:   title: string;
12: }
13: 
14: export function buildKnowledgeCodeLensModels(
15:   entities: KnowledgeEntity[],
16:   relations: KnowledgeRelation[],
17:   lineCount: number,
18:   getObservationCount: (entityId: string) => number
19: ): KnowledgeCodeLensModel[] {
20:   const relationCounts = new Map<string, number>();
21:   for (const relation of relations) {
22:     relationCounts.set(
23:       relation.sourceEntityId,
24:       (relationCounts.get(relation.sourceEntityId) || 0) + 1
25:     );
26:     relationCounts.set(
27:       relation.targetEntityId,
28:       (relationCounts.get(relation.targetEntityId) || 0) + 1
29:     );
30:   }
31: 
32:   return entities.flatMap((entity) => {
33:     if (entity.startLine < 1 || entity.startLine > lineCount) {
34:       return [];
35:     }
36: 
37:     const description = compactDescription(entity.description) || entity.name;
38:     const observationCount = getObservationCount(entity.id);
39:     const relationCount = relationCounts.get(entity.id) || 0;
40:     return [
41:       {
42:         entityId: entity.id,
43:         line: entity.startLine - 1,
44:         title: `🧠 KG: ${description} · 📝 ${observationCount} · 🔗 ${relationCount}`,
45:       },
46:     ];
47:   });
48: }
49: 
50: function compactDescription(description?: string): string {
51:   const compact = description?.replace(/\s+/g, ' ').trim() || '';
52:   if (compact.length <= MAX_DESCRIPTION_LENGTH) {
53:     return compact;
54:   }
55:   return `${compact.slice(0, MAX_DESCRIPTION_LENGTH - 1)}…`;
56: }
