1: import { describe, expect, it, vi } from 'vitest';
2: import type {
3:   KnowledgeEntity,
4:   KnowledgeRelation,
5: } from '../services/knowledgeGraphService';
6: import { buildKnowledgeCodeLensModels } from './knowledgeCodeLensModel';
7: 
8: describe('buildKnowledgeCodeLensModels', () => {
9:   it('shows Agent descriptions and unified graph statistics', () => {
10:     const agentEntity = entity({
11:       id: 'agent-a',
12:       name: 'AgentService',
13:       description: '  Generated by the Agent\nfrom source evidence.  ',
14:       origin: 'agent',
15:     });
16:     const secondAgentEntity = entity({
17:       id: 'agent-b',
18:       name: 'SecondaryService',
19:       description: 'Human description',
20:       origin: 'agent',
21:       startLine: 20,
22:     });
23:     const relations: KnowledgeRelation[] = [
24:       {
25:         id: 'relation-a-b',
26:         sourceEntityId: agentEntity.id,
27:         targetEntityId: secondAgentEntity.id,
28:         verb: 'depends_on',
29:         createdAt: 1,
30:         origin: 'agent',
31:       },
32:     ];
33:     const getObservationCount = vi.fn((id: string) =>
34:       id === secondAgentEntity.id ? 2 : 0
35:     );
36: 
37:     const models = buildKnowledgeCodeLensModels(
38:       [agentEntity, secondAgentEntity],
39:       relations,
40:       100,
41:       getObservationCount
42:     );
